-- Additional PHY 122 CBT questions on mirrors/reflection, mined from a
-- user-supplied practice sheet. 10 rows appended to the existing
-- bank (2 questions from the same sheet were dropped as exact duplicates
-- already present). Every numeric answer independently verified with sympy.

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A man stands $50\ \text{cm}$ from a concave mirror having a radius of curvature $10\ \text{cm}$. Find the position of the image and the magnification.', '["$5.56\\ \\text{cm}$, $0.11$", "$6.65\\ \\text{cm}$, $0.12$", "$7.55\\ \\text{cm}$, $0.13$", "$7.80\\ \\text{cm}$, $0.14$"]'::jsonb, 0, 'The focal length is $f = R/2 = 5\ \text{cm}$. Using $\dfrac{1}{v} + \dfrac{1}{u} = \dfrac{1}{f}$ with $u = 50\ \text{cm}$: $\dfrac{1}{v} = \dfrac{1}{5} - \dfrac{1}{50} = \dfrac{9}{50}$, so $v = \dfrac{50}{9} \approx 5.56\ \text{cm}$. The magnification is $|m| = v/u = 5.56/50 \approx 0.11$.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Where must an object be placed with respect to a convex mirror of focal length $30\ \text{cm}$, in order to obtain an image one-third as far behind the mirror as the object is in front of it?', '["$50.00\\ \\text{cm}$", "$60.00\\ \\text{cm}$", "$65.00\\ \\text{cm}$", "$55.00\\ \\text{cm}$"]'::jsonb, 1, 'For a convex mirror, $f = -30\ \text{cm}$, and the virtual image distance is $v = -u/3$. Substituting into $\dfrac{1}{u} + \dfrac{1}{v} = \dfrac{1}{f}$: $\dfrac{1}{u} - \dfrac{3}{u} = -\dfrac{1}{30} \Rightarrow -\dfrac{2}{u} = -\dfrac{1}{30} \Rightarrow u = 60\ \text{cm}$.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'An object $5\ \text{cm}$ high placed $10\ \text{cm}$ from a curved mirror produces a virtual image of height $6.5\ \text{cm}$. Where is the image located, and what type of mirror is this?', '["$-13.00\\ \\text{cm}$, concave mirror", "$-14.00\\ \\text{cm}$, concave mirror", "$-13.00\\ \\text{cm}$, convex mirror", "$-14.00\\ \\text{cm}$, convex mirror"]'::jsonb, 0, 'The image is magnified ($6.5/5 = 1.3$) and upright, so $m = -v/u = 1.3$, giving $v = -1.3 \times 10 = -13\ \text{cm}$ (virtual, behind the mirror). Only a concave mirror can form a magnified, upright, virtual image (when the object sits between the pole and the focus) -- a convex mirror always diminishes.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Light rays intercept a plane mirror at an angle of $35^{\circ}$ measured from the normal to the surface. Find the angle between the incident and reflected rays.', '["$70^{\\circ}$", "$80^{\\circ}$", "$60^{\\circ}$", "$50^{\\circ}$"]'::jsonb, 0, 'The law of reflection gives an angle of reflection equal to the angle of incidence, $35^{\circ}$, both measured from the normal. The angle between the incident and reflected rays is the sum of the two: $35^{\circ} + 35^{\circ} = 70^{\circ}$.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'An object is placed in front of a convex mirror of focal length $15\ \text{cm}$. The image forms $10\ \text{cm}$ from the mirror. Find the object distance.', '["$30.00\\ \\text{cm}$", "$25.00\\ \\text{cm}$", "$35.00\\ \\text{cm}$", "$40.00\\ \\text{cm}$"]'::jsonb, 0, 'For a convex mirror, $f = -15\ \text{cm}$ and the image is virtual, so $v = -10\ \text{cm}$. Using $\dfrac{1}{u} + \dfrac{1}{v} = \dfrac{1}{f}$: $\dfrac{1}{u} = -\dfrac{1}{15} + \dfrac{1}{10} = \dfrac{1}{30}$, so $u = 30\ \text{cm}$.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'An object is placed at infinity in front of a concave mirror. Where will the image form, and what is its nature?', '["At the principal focus; real, diminished and inverted", "At the centre of curvature; real, magnified and inverted", "At the principal focus; virtual, diminished and inverted", "At the centre of curvature; real, diminished and inverted"]'::jsonb, 0, 'Parallel rays from an object at infinity converge at the principal focus after reflection, forming a real, inverted, point-like (highly diminished) image there.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Which of the following best describes a translucent material?', '["It allows all light to pass straight through, giving a clear view of objects behind it", "It allows light to pass through but scatters it, so objects behind it cannot be seen clearly", "It blocks all light from passing through", "It reflects essentially all incident light, like a mirror"]'::jsonb, 1, 'A translucent material (e.g. frosted glass) transmits light but scatters it in the process, so light passes through without a clear image of what''s behind -- unlike a transparent material, which transmits light with a clear view, or an opaque material, which blocks light entirely.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'What is the key property that distinguishes a real image from a virtual image?', '["A real image can be formed on a screen, since light rays actually converge there", "A real image is always larger than the object", "A real image is always upright", "A real image can only be formed by a plane mirror"]'::jsonb, 0, 'A real image forms where reflected (or refracted) light rays actually converge, so it can be captured on a screen; a virtual image forms where rays only appear to diverge from, and can never be projected onto a screen. Size and orientation depend on the specific setup, not on whether the image is real or virtual.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Why is the principal focus of a convex mirror described as virtual?', '["Because the reflected rays only appear to diverge from that point behind the mirror, rather than actually passing through it", "Because a convex mirror does not really have a focus", "Because light rays actually converge and pass through that point behind the mirror", "Because convex mirrors only work with virtual objects"]'::jsonb, 0, 'A convex mirror is diverging: parallel rays striking it spread out after reflection, but if extended backward behind the mirror, they appear to meet at a single point -- the virtual principal focus. No real light actually passes through that point.', 'Reflection, refraction, mirrors and lenses', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'As an object is moved from infinity toward the focal point of a concave mirror, how does the size of the real image it forms change?', '["It steadily grows larger, becoming very large as the object approaches the focal point", "It stays the same size throughout", "It steadily shrinks toward zero", "It disappears immediately once the object leaves infinity"]'::jsonb, 0, 'At infinity the image is a point at the focus (most diminished). As the object moves inward toward the focus, the real image moves outward and grows continuously larger, becoming very large just before the object reaches the focal point (at which point the image forms at infinity).', 'Reflection, refraction, mirrors and lenses', false, 'second', 3);
